@Injectable()
export class AuthGuard implements CanActivate {
  async canActivate(ctx: ExecutionContext) {
    const req = ctx.switchToHttp().getRequest();
    req.user = await this.auth.verifyBearer(req.headers.authorization);
    return true;
  }
}

